"""Private saved-intake photo preview and editing controls for Admin."""

MEDIA_MANAGEMENT_CSS = r'''
.owner-media-editor{margin:12px 0 18px;padding:14px;border:1px solid #dce4ef;border-radius:14px;background:#f8faff}
.owner-media-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:10px}.owner-media-toolbar button{min-height:42px}
.owner-media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:9px}
.owner-media-card{min-width:0;margin:0;padding:7px;border:1px solid #dce4ef;border-radius:11px;background:#fff}
.owner-media-thumb{display:block;width:100%;height:90px;object-fit:cover;border-radius:7px;background:#edf1f6;cursor:zoom-in}
.owner-media-card figcaption{margin:5px 0;font-size:.75rem;overflow-wrap:anywhere}.owner-media-card button{min-height:36px;padding:5px 8px;margin:3px 2px 0 0;font-size:.75rem}
.owner-media-status{min-height:1.4em;margin:7px 0 0}.owner-media-private{color:#69778a}
.owner-media-preview{width:min(94vw,900px);max-height:92dvh;margin:auto;padding:14px;border:0;border-radius:16px}.owner-media-preview::backdrop{background:#101b2eaa}
.owner-media-preview img{display:block;max-width:88vw;max-height:76dvh;margin:auto;object-fit:contain}.owner-media-preview p{text-align:center}
@media(max-width:699px){.owner-media-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.owner-media-thumb{height:78px}.owner-media-toolbar button{flex:1}}
'''

MEDIA_MANAGEMENT_SCRIPT = r'''<script>
(()=>{'use strict';const host=document.querySelector('#review-detail');if(!host)return;let reviewId='',editor=null,galleryRef=null;
const messageText=(status,data)=>{if(status===409&&data.error==='STALE_INTAKE_MEDIA_REVISION')return'Ảnh đã được cập nhật ở phiên khác. Hãy tải lại nguồn.';if(data.error==='MEDIA_EDIT_GATE_A_PROTECTED')return'Gate A đã duyệt; không thể đổi ảnh trong revision này.';if(data.error==='DUPLICATE_MEDIA')return'Ảnh này đã có trong sản phẩm hoặc lịch sử nguồn.';if(data.error==='MEDIA_IMAGE_TYPE_OR_SIZE_INVALID')return'Ảnh không hợp lệ hoặc vượt giới hạn 25 MB.';return data.error||('HTTP '+status)};
function preview(src,caption){const d=document.createElement('dialog');d.className='owner-media-preview';const img=document.createElement('img');img.src=src;img.alt=caption;const p=document.createElement('p');p.textContent=caption;const close=document.createElement('button');close.type='button';close.className='secondary';close.textContent='Đóng';close.onclick=()=>d.close();d.append(img,p,close);d.addEventListener('close',()=>d.remove(),{once:true});document.body.append(d);d.showModal()}
async function submit(intake,action,revision,mediaId,files){const status=editor?.querySelector('[data-media-status]');const allowed=new Set(['image/jpeg','image/png','image/webp','image/avif']);const extAllowed=/\.(jpe?g|png|webp|avif)$/i;if((files||[]).some(f=>f.size>25*1024*1024||(!allowed.has(f.type)&&!extAllowed.test(f.name)))){if(status){status.className='owner-media-status err';status.textContent='Chỉ nhận JPEG, PNG, WebP hoặc AVIF, tối đa 25 MB mỗi ảnh.'}return}let saved=false;if(status){status.className='owner-media-status';status.textContent='Đang lưu ảnh…'}const data=new FormData();data.append('action',action);data.append('expected_media_revision',String(revision));if(mediaId)data.append('media_id',mediaId);for(const f of files||[])data.append('media',f,f.name);try{const response=await fetch('/api/intakes/'+encodeURIComponent(intake)+'/media-edit',{method:'POST',credentials:'same-origin',body:data});let result={};try{result=await response.json()}catch(_){}if(!response.ok)throw Error(messageText(response.status,result));saved=true;const list=await fetch('/api/intakes',{credentials:'same-origin',cache:'no-store'});if(!list.ok)throw Error('INTAKE_LIST_REFRESH_FAILED');window.intakeRecords=await list.json();await window.loadReview?.(reviewId);const refreshed=editor?.querySelector('[data-media-status]');if(refreshed){refreshed.className='owner-media-status';refreshed.textContent='Đã lưu · '+result.media.length+' ảnh · media r'+result.media_revision+' · quyền ảnh vẫn chưa được duyệt.'}}catch(error){const currentStatus=editor?.querySelector('[data-media-status]')||status;if(currentStatus){currentStatus.className=saved?'owner-media-status':'owner-media-status err';currentStatus.textContent=saved?'Ảnh đã lưu nhưng chưa tải lại được danh sách. Tải lại review trước khi tiếp tục.':'Không lưu được: '+error.message}}}
function install(){const gallery=host.querySelector('[data-owner-source-gallery]');const pkg=window.currentReviewPackage;const record=(window.intakeRecords||[]).find(row=>row.id===pkg?.candidate?.intake_id||row.contentReviewId===pkg?.review_id);if(!gallery||!record)return;if(galleryRef===gallery&&editor?.isConnected)return;gallery.hidden=true;gallery.style.display='none';const priorLabel=gallery.previousElementSibling;if(priorLabel?.classList.contains('muted')&&/^\d+ ảnh nguồn/.test(priorLabel.textContent||''))priorLabel.remove();galleryRef=gallery;editor?.remove();editor=document.createElement('section');editor.className='owner-media-editor';editor.setAttribute('aria-label','Quản lý ảnh nguồn của sản phẩm');const toolbar=document.createElement('div');toolbar.className='owner-media-toolbar';const count=document.createElement('span');count.textContent=(record.media||[]).length+' ảnh đã chọn · đang tải preview';count.className='owner-media-private';const add=document.createElement('button');add.type='button';add.className='secondary';add.textContent='Thêm ảnh';const addInput=document.createElement('input');addInput.type='file';addInput.accept='image/jpeg,image/png,image/webp,image/avif';addInput.multiple=true;addInput.hidden=true;add.onclick=()=>addInput.click();addInput.onchange=()=>{const files=Array.from(addInput.files||[]);addInput.value='';if(files.length)submit(record.id,'add',Number(record.mediaRevision||1),'',files)};toolbar.append(count,add);editor.append(toolbar,addInput);const grid=document.createElement('div');grid.className='owner-media-grid';const updateCount=()=>{const images=Array.from(grid.querySelectorAll('img')),loaded=images.filter(image=>image.complete&&image.naturalWidth>0).length,failed=images.filter(image=>image.complete&&image.naturalWidth===0).length;count.textContent=(record.media||[]).length+' ảnh đã chọn · '+loaded+'/'+images.length+' preview tải được'+(failed?' · lỗi '+failed:'')};for(const item of(record.media||[])){const mediaId=item.mediaId||item.media_id;if(!mediaId)continue;const fig=document.createElement('figure');fig.className='owner-media-card';const img=document.createElement('img');img.className='owner-media-thumb';img.src='/api/intakes/'+encodeURIComponent(record.id)+'/media/'+encodeURIComponent(mediaId);img.alt=item.filename||'Ảnh nguồn';img.loading='eager';img.decoding='async';img.onclick=()=>preview(img.src,img.alt);img.onerror=()=>{img.alt='Không tải được ảnh';img.dataset.loadState='failed';updateCount()};img.onload=()=>{img.dataset.loadState=img.naturalWidth>0?'loaded':'failed';updateCount()};const cap=document.createElement('figcaption');cap.textContent=(item.filename||mediaId)+' · quyền: CHƯA DUYỆT · riêng tư';const replace=document.createElement('button');replace.type='button';replace.className='secondary';replace.textContent='Thay ảnh';const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp,image/avif';input.hidden=true;replace.onclick=()=>input.click();input.onchange=()=>{const file=input.files?.[0];input.value='';if(file)submit(record.id,'replace',Number(record.mediaRevision||1),mediaId,[file])};const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Xóa';remove.onclick=()=>{if(window.confirm('Bỏ ảnh này khỏi bộ ảnh đang chọn? File nguồn được giữ trong lịch sử và không bị xóa.'))submit(record.id,'remove',Number(record.mediaRevision||1),mediaId,[])};fig.append(img,cap,replace,input,remove);grid.append(fig)}editor.append(grid);updateCount();const status=document.createElement('p');status.dataset.mediaStatus='true';status.className='owner-media-status';status.textContent='Ảnh mới/thay thế mặc định ở trạng thái chưa duyệt quyền sử dụng. Gate A đã duyệt thì bộ ảnh được khóa cho revision này.';editor.append(status);gallery.after(editor)}
const observer=new MutationObserver(()=>{const id=window.currentReviewPackage?.review_id||'';if(id)reviewId=id;install()});observer.observe(host,{childList:true,subtree:true});reviewId=window.currentReviewPackage?.review_id||'';install();
})();</script>'''
